# ---- global: the generic team entry (D-21, R1-009) in every scenario and criterion
def entry_shape(s):
  s=re.sub(r'"lead":"([^"]*)","members":(\[[^\]]*\])',r'"people":{"lead":"\1"},"lists":{"members":\2}',s)
  s=s.replace('at "teams.gold.lead"','at "teams.gold.people.lead"').replace('teams.t1.lead: must match','teams.t1.people.lead: must match')
  s=s.replace('teams.t2.members: must have at least 1 entries','teams.t2.lists.members: must not be empty (workflow team)').replace('teams.t1.members: must have at least 1 entries','teams.t1.lists.members: must not be empty (workflow team)')
  s=s.replace('teams.t1.lead: the lead is not one of the members','teams.t1: lead and members must not share a name (b)')
  s=re.sub(r'has the entry key (external_reviewers|review_only|members) set to',r'has the entry list \1 set to',s)
  s=re.sub(r'has the entry key refinement_review set to',r'has the entry rule refinement_review set to',s)
  s=s.replace('"handoff_states":["accepted","legacy"]','"handoff_states":["accepted","unrecorded"]')
  return s
for r in REQS:
  r['scen']=[(t,entry_shape(g)) for t,g in r['scen']]
  r['accept']=[entry_shape(a) for a in r['accept']]
  r['statement']=entry_shape(r['statement'])
